import unittest
import copy
import json
import tempfile
from pathlib import Path
from unittest.mock import patch

import numpy as np

import hncs_pipeline as h
from phocus_presets import (FACTORY_SETTING_FILES, PRESET_CHOICES, apply_preset,
                            apply_post_curves, catalog, preset_key, resolve_crop, resolve_film_curve, settings)


class PhocusPresetTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.assets = h.load_assets()

    def test_catalog_contains_all_extracted_factory_settings(self):
        names = catalog()["factory_setting_names"]
        self.assertEqual(names[:4], ["Standard", "Product", "Portrait", "Nature"])
        self.assertIn("Square Crop", names)
        self.assertIn("Tungsten", names)

    def test_every_extracted_settings_file_has_a_portable_key(self):
        source_files = set(catalog()["source_files"])
        mapped_files = set(FACTORY_SETTING_FILES.values())
        self.assertEqual(source_files, mapped_files)
        self.assertGreaterEqual(len(PRESET_CHOICES), len(source_files))
        for key in PRESET_CHOICES:
            self.assertEqual(settings(key)["name"], preset_key(key))

    def test_native_curve_families_and_as_shot_resolution(self):
        standard, p_standard = resolve_film_curve("standard", self.assets, working_space="legacy")
        as_shot, p_as_shot = resolve_film_curve("as-shot", self.assets, working_space="legacy", raw_film_curve=2)
        old, p_old = resolve_film_curve("old-standard", self.assets, working_space="legacy")
        linear, p_linear = resolve_film_curve("linear", self.assets, working_space="legacy")
        repro, p_repro = resolve_film_curve("standard", self.assets, intent="reproduction", working_space="legacy")
        self.assertEqual(p_as_shot["resolved_film_curve_type"], 2)
        self.assertEqual(p_standard["resolved_film_curve_type"], 2)
        self.assertEqual(p_old["resolved_film_curve_type"], 0)
        self.assertEqual(p_linear["resolved_film_curve_type"], 7)
        self.assertEqual(p_repro["resolved_film_curve_type"], 7)
        self.assertTrue(np.array_equal(standard, as_shot))
        self.assertFalse(np.array_equal(standard, old))
        self.assertFalse(np.array_equal(standard, linear))
        self.assertTrue(np.array_equal(linear, repro))

    def test_nature_tone_and_saturation_presets_change_codes(self):
        source = np.linspace(0, 65535, 17, dtype=np.uint16).reshape(1, 17, 1)
        source = np.repeat(source, 3, axis=2)
        nature, nature_meta = apply_preset(source, "nature")
        standard, _ = apply_preset(source, "standard")
        self.assertTrue(nature_meta["tone_curve_applied"])
        self.assertFalse(np.array_equal(nature, standard))
        self.assertLess(int(nature[0, 5, 0]), int(standard[0, 5, 0]))
        saturated_source = np.array([[[10000, 30000, 50000]]], dtype=np.uint16)
        saturated, saturated_meta = apply_preset(saturated_source, "saturated")
        self.assertEqual(saturated_meta["saturation_applied"], 10.0)
        self.assertGreater(int(saturated[0, 0, 2] - saturated[0, 0, 0]),
                           int(saturated_source[0, 0, 2] - saturated_source[0, 0, 0]))

    def test_factory_curves_against_independent_native_filter_vectors(self):
        # Inputs and outputs were captured by CGradationFilter from the actual
        # Phocus XML, not generated by the production Python renderer.
        evidence = catalog()["binary_evidence"]["post_curves"]
        fixture = h.WORK / "evidence/native_preset_vectors.npz"
        with np.load(fixture, allow_pickle=False) as vectors:
            for rel, name in (("Nature.xml", "nature"),
                              ("Gradation Curves/Lighten.xml", "lighten"),
                              ("Exposure/Extra contrast.xml", "extra-contrast")):
                for tone in (True, False):
                    mode = evidence["source_files"][rel]["modes"]["tone" if tone else "no_tone"]
                    key = mode["vector_key"]
                    if not tone and name != "extra-contrast":
                        actual, meta = apply_post_curves(vectors[key+"_source"], name, apply_tone_curve=False)
                        np.testing.assert_array_equal(actual, vectors[key+"_source"])
                        self.assertFalse(meta["tone_curve_applied"])
                        continue
                    with self.subTest(preset=name, tone=tone):
                        actual, meta = apply_post_curves(vectors[key+"_source"], name, apply_tone_curve=tone)
                        np.testing.assert_array_equal(actual, vectors[key+"_output"])
                        ramp = np.repeat(np.arange(65536, dtype=np.uint16)[:, None], 3, axis=1)
                        actual_ramp, _ = apply_post_curves(ramp, name, apply_tone_curve=tone)
                        np.testing.assert_array_equal(actual_ramp, vectors[key+"_ramp"])
                        if name == "extra-contrast":
                            self.assertTrue(meta["gamma_applied"])
                            self.assertAlmostEqual(meta["effective_gamma"], 1.2, places=6)
                            self.assertTrue(meta["contrast_hue_recovery"])

    def test_native_point_curve_samples_and_gamma_are_applied_by_render(self):
        import tifffile
        # Nature control point (71,31) is not an interpolation node.
        value = np.full((1,1,3), 71*257, dtype=np.uint16)
        nature, _ = apply_preset(value, "nature", apply_sharpness=False)
        self.assertEqual(int(nature[0,0,0]), 15552)
        profile = json.loads(h.PROFILE.read_text())
        metadata = dict(profile["source"], sha256="native preset integration", orientation=1)
        image = np.random.default_rng(91).integers(200, 12000, (32,48,3), dtype=np.uint16)
        with tempfile.TemporaryDirectory() as folder:
            arrays = {}
            for name in ("standard", "extra-contrast"):
                output = Path(folder)/f"{name}.tif"
                args = h.parser().parse_args(["render", "--preset", name, "--no-sharpness", "--output", str(output)])
                with patch.object(h,"demosaic",return_value=(image.copy(),metadata)):
                    run = h.render(args,self.assets,profile)
                arrays[name] = tifffile.imread(output)
                if name == "extra-contrast":
                    self.assertTrue(run["preset"]["gamma_applied"])
                    self.assertEqual(run["preset"]["contrast_applied"], 10.)
                    self.assertEqual(run["preset"]["preset_settings"]["ev"], 1)
            expected, _ = apply_preset(arrays["standard"], "extra-contrast", apply_sharpness=False)
            np.testing.assert_array_equal(arrays["extra-contrast"], expected)

    def test_portrait_product_presets_preserve_color_core_and_record_sharpness(self):
        source = np.array([[[10000, 20000, 30000]]], dtype=np.uint16)
        for name, amount in (("portrait", 90), ("product", 350)):
            output, meta = apply_preset(source, name)
            self.assertTrue(np.array_equal(output, source))
            self.assertEqual(meta["preset_settings"]["sharpness"]["amount"], amount)
            self.assertFalse(meta["sharpness_requested"])

    def test_native_white_balance_and_film_grain_presets_are_applied(self):
        daylight = settings("daylight")
        nature = settings("nature")
        self.assertEqual(daylight["native_wb_gains"], nature["native_wb_gains"])
        self.assertAlmostEqual(daylight["native_wb_gains"][1], 1.0)
        source = np.full((32, 32, 3), 30000, dtype=np.uint16)
        output, meta = apply_preset(source, "film-grain-fine-texture")
        self.assertTrue(meta["film_grain_requested"])
        self.assertTrue(meta["film_grain_applied"])
        self.assertFalse(np.array_equal(output, source))
        output2, meta2 = apply_preset(source, "film-grain-fine-texture")
        self.assertTrue(np.array_equal(output, output2))
        self.assertTrue(meta2["film_grain_applied"])
        rows = catalog()["binary_evidence"]["white_balance_presets"]["rows"]
        for name, row in rows.items():
            cfg = settings(name)
            self.assertTrue(np.allclose(cfg["native_wb_gains"], row["normalized_gains"], atol=0, rtol=0))
            self.assertTrue(np.allclose(cfg["native_tint_multiplier"], row["tint_multiplier"], atol=0, rtol=0))

    def test_all_extracted_presets_execute_the_portable_entrypoint(self):
        source = np.zeros((8, 8, 3), dtype=np.uint16)
        source[2:6, 2:6] = [10000, 30000, 50000]
        for rel in catalog()["source_files"]:
            key = next(k for k, filename in FACTORY_SETTING_FILES.items() if filename == rel)
            output, meta = apply_preset(source, key, apply_sharpness=True)
            self.assertEqual(output.shape, source.shape, key)
            self.assertEqual(meta["preset"], preset_key(key))

    def test_explicit_sharpness_switch_applies_portable_filter(self):
        source = np.zeros((9, 9, 3), dtype=np.uint16)
        source[4, 4] = 40000
        output, meta = apply_preset(source, "product", apply_sharpness=True)
        self.assertTrue(meta["sharpness_requested"])
        self.assertTrue(meta["sharpness_applied"])
        self.assertFalse(np.array_equal(output, source))

    def test_white_balance_gains_match_configured_native_camera_and_roundtrip(self):
        # Independently recorded from the configured Phocus 4.2.2 native
        # objects; the previous generic-camera extraction fails these values.
        expected = {"daylight": [2.711552043782954,1.,1.690108149776517],
                    "tungsten": [1.6435585674015674,1.,3.051623849435867]}
        for name, gains in expected.items():
            np.testing.assert_allclose(settings(name)["native_wb_gains"], gains, rtol=0, atol=1e-12)
        for name in ("cloudy","daylight","flash","fluorescent","shade","tungsten"):
            cfg = settings(name)
            cct, tint = h.estimate_cct(cfg["native_wb_gains"],self.assets)
            self.assertAlmostEqual(cct,cfg["color_temperature"],delta=1)
            self.assertAlmostEqual(tint,cfg["tint"],delta=1e-5)
        broken = copy.deepcopy(catalog())
        broken["binary_evidence"]["white_balance_presets"].pop("factory_configuration_loaded")
        with patch("phocus_presets.catalog",return_value=broken):
            with self.assertRaises(ValueError): settings("daylight")

    def test_absolute_wb_preset_neutralises_the_selected_target_illuminant(self):
        profile = json.loads(h.PROFILE.read_text())
        capture = np.array(profile["source_wb"])
        target_capture = np.array(profile["target_wb"])
        # Start with a sensor neutral under the selected WB, expressed through
        # the independently fitted daylight camera response. Merely changing
        # the factory CCT leaves this neutral strongly coloured.
        response = np.asarray(profile["matrix"])*capture[None,:]/target_capture[:,None]
        for name in ("daylight","tungsten","fluorescent"):
            cfg = settings(name); desired = np.array(cfg["native_wb_gains"])
            target_neutral = .12/desired
            source_neutral = np.linalg.solve(response,target_neutral)
            for mode in ("paired","adaptive","dual","calibration"):
                params = h.render_colour_parameters(profile,self.assets,capture,"camera",mode,
                    cfg["color_temperature"],target_wb_override=desired)
                mapped = (source_neutral*capture) @ np.asarray(params["matrix"]).T
                np.testing.assert_allclose(mapped,[.12]*3,rtol=0,atol=2e-15)
            params = h.render_colour_parameters(profile,self.assets,target_capture,"camera","paired",
                cfg["color_temperature"],target_reference=True,target_wb_override=desired)
            mapped = (target_neutral*target_capture) @ np.asarray(params["matrix"]).T
            np.testing.assert_allclose(mapped,[.12]*3,rtol=0,atol=2e-15)
        base = h.render_colour_parameters(profile,self.assets,[2.,1.,2.],"camera","paired")
        changed = h.render_colour_parameters(profile,self.assets,[2.,1.,2.],"camera","paired",2850,
            target_wb_override=settings("tungsten")["native_wb_gains"])
        self.assertEqual(base["paired_warm_weight"],changed["paired_warm_weight"])
        self.assertEqual(base["source_estimated_cct"],changed["source_estimated_cct"])
        self.assertFalse(np.allclose(base["matrix"],changed["matrix"]))

    def test_square_crop_fits_each_camera_including_portrait_and_odd_sizes(self):
        cfg = settings("square-crop")
        for shape in ((6374,9566,3),(8842,11904,3),(9566,6374,3),(641,960,3)):
            crop = resolve_crop(shape,cfg)
            left,top,right,bottom = crop["pixel_bounds"]
            self.assertEqual(right-left,bottom-top)
            self.assertEqual(right-left,min(shape[:2]))
            self.assertLessEqual(abs(left-(shape[1]-right)),1)
            self.assertLessEqual(abs(top-(shape[0]-bottom)),1)
        self.assertIsNone(resolve_crop((64,96,3),settings("standard")))
        ordinary = resolve_crop((80,120,3),{"crop":{"Left":.25,"Right":.75,"Top":0.,"Bottom":1.}})
        self.assertEqual(ordinary["pixel_bounds"],[30,0,90,80])

    def test_render_wires_absolute_white_balance_and_square_crop_to_tiff(self):
        import tifffile
        profile = json.loads(h.PROFILE.read_text())
        metadata = dict(profile["source"])
        metadata["sha256"] = "synthetic integration input"
        metadata["orientation"] = 1
        image = np.full((64,96,3),8000,dtype=np.uint16)
        with tempfile.TemporaryDirectory() as folder:
            for name in ("tungsten","square-crop"):
                output = Path(folder)/f"{name}.tif"
                args = h.parser().parse_args(["render","--preset",name,"--no-sharpness","--output",str(output)])
                with patch.object(h,"demosaic",return_value=(image.copy(),metadata)):
                    run = h.render(args,self.assets,profile)
                with tifffile.TiffFile(output) as tif:
                    self.assertEqual(tif.pages[0].shape,(64,64,3) if name=="square-crop" else (64,96,3))
                    self.assertEqual(tif.pages[0].tags[34675].value,self.assets["legacy_icc"])
                if name=="tungsten":
                    self.assertTrue(run["target_white_balance_override_applied"])
                    np.testing.assert_allclose(run["estimated_target_white_balance"],settings(name)["native_wb_gains"],atol=1e-12,rtol=0)


if __name__ == "__main__":
    unittest.main()
